declare(strict_types=1);require __DIR__.'/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM seed_count_records WHERE id=?');$st->execute([$id]);$x=$st->fetch();if(!$x){http_response_code(404);exit('記録がありません');}$ob=db()->prepare('SELECT * FROM seed_morphology_objects WHERE record_id=? ORDER BY object_number');$ob->execute([$id]);$objects=$ob->fetchAll();$analysis=json_decode((string)($x['analysis_json']??''),true)?:[];$summary=$analysis['summary']??[];$autoCount=count($objects);$corrected=(int)$x['seed_count'];$corrections=[];try{$cs=db()->prepare('SELECT * FROM seed_manual_corrections WHERE record_id=? ORDER BY id DESC LIMIT 10');$cs->execute([$id]);$corrections=$cs->fetchAll();}catch(Throwable$e){}
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css?v=2.1.0"><title>形態解析詳細</title></head><body><header><h1>Seed Morphology 詳細</h1><nav><a href="history.php">履歴</a><a href="correction.php?id=<?=$id?>">手動カウント補正</a><a href="reanalyze.php?id=<?=$id?>">再解析</a><a href="download.php?id=<?=$id?>&amp;type=original">元画像DL</a><a href="download.php?id=<?=$id?>&amp;type=result">結果DL</a><a href="export_objects_csv.php?id=<?=$id?>">個体CSV</a><a href="index.php">新規解析</a></nav></header><main><section class="card"><div class="count"><span><?=number_format($corrected)?></span><b>粒</b></div><?php if($corrected!==$autoCount):?><p><b>手動補正済み</b>（自動検出 <?=$autoCount?>粒 → 補正後 <?=$corrected?>粒）</p><?php endif;?><p><?=h($x['device_name'])?>／<?=h($x['memo'])?>／<?=h($x['created_at'])?></p><div class="compare"><figure><figcaption>元画像</figcaption><img src="<?=h($x['original_path'])?>"></figure><figure><figcaption>解析結果</figcaption><img src="<?=h($x['result_path'])?>"></figure></div></section><section class="card"><h2>全体統計</h2><div class="stats-grid"><?php foreach([['平均面積',$x['mean_area_px2'].' px²'],['平均長径',$x['mean_major_axis_px'].' px'],['平均短径',$x['mean_minor_axis_px'].' px'],['平均円形度',$x['mean_circularity']],['面積CV',($summary['area_px2']['cv_percent']??'-').' %'],['処理時間',$x['processing_ms'].' ms']]as$v):?><div><b><?=h($v[0])?></b><span><?=h($v[1])?></span></div><?php endforeach;?></div></section><?php if($corrections):?><section class="card"><h2>手動補正履歴</h2><div class="table-wrap"><table><thead><tr><th>日時</th><th>自動</th><th>補正後</th><th>メモ</th></tr></thead><tbody><?php foreach($corrections as$c):?><tr><td><?=h($c['created_at'])?></td><td><?=h($c['automatic_count'])?></td><td><?=h($c['corrected_count'])?></td><td><?=h($c['note'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><section class="card"><h2>個体別データ</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>面積</th><th>周囲長</th><th>長径</th><th>短径</th><th>比</th><th>円形度</th><th>充実度</th><th>Extent</th><th>向き</th></tr></thead><tbody><?php foreach($objects as$o):?><tr><td><?=h($o['object_number'])?></td><td><?=h($o['area_px2'])?></td><td><?=h($o['perimeter_px'])?></td><td><?=h($o['major_axis_px'])?></td><td><?=h($o['minor_axis_px'])?></td><td><?=h($o['aspect_ratio'])?></td><td><?=h($o['circularity'])?></td><td><?=h($o['solidity'])?></td><td><?=h($o['extent'])?></td><td><?=h($o['orientation_deg'])?>°</td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
